var UserConnection = Get<UserConnection>("UserConnection");
string storeId = Get<string>("StoreId");
string deviceItems = Get<string>("DeviceIds");
Guid lineDetailId = Get<Guid>("LineDetail");
bool sendRequest = Get<bool>("SendRequest");
string lineDetailIds = Get<string>("LineDetailIds");


var reserveStock = new ReserveStock(UserConnection);
var dmsService = new DMSService(UserConnection);

try {
	if (!string.IsNullOrEmpty(storeId) && !string.IsNullOrEmpty(deviceItems)) {
		List<string> deviceItemList = deviceItems.Split(',').ToList();
		var result = reserveStock.GetParam(storeId, deviceItemList);
		Set("RequestBody", result.ToString());

		if (sendRequest) {
			var response = dmsService.ReserveStock(result).GetAwaiter().GetResult();
			Set("ResponseBody", JsonConvert.SerializeObject(response, Formatting.Indented));
		}
	} else if (lineDetailId != Guid.Empty) {
		var result = reserveStock.GetParam(lineDetailId);
		Set("RequestBody", result.ToString());

		if (sendRequest) {
			var response = dmsService.ReserveStock(result).GetAwaiter().GetResult();
			Set("ResponseBody", JsonConvert.SerializeObject(response, Formatting.Indented));
		}
	} else if (!string.IsNullOrEmpty(lineDetailIds)) {
		var lineDetailList = lineDetailIds.Split(',').Select(item => Guid.Parse(item)).ToList();
		var result = reserveStock.GetParamList(lineDetailList);
		Set("RequestBody", JsonConvert.SerializeObject(result, Formatting.Indented));

		if (sendRequest) {
			var response = dmsService.ReserveStockBatch(lineDetailList).GetAwaiter().GetResult();
			Set("ResponseBody", JsonConvert.SerializeObject(response, Formatting.Indented));
		}
	}
} catch (Exception e) {
	Set("Message", e.Message);
}




return true;
